/// The larger of two numbers.
fn larger(a: i32, b: i32) -> i32 {
    if a > b {
        a
    } else {
        b
    }
}

/// -1, 0 or 1, depending on the sign of n.
fn sign(n: i32) -> i32 {
    if n < 0 {
        -1
    } else if n == 0 {
        0
    } else {
        1
    }
}

/// A name for the wind speed.
fn wind(knots: u32) -> &'static str {
    match knots {
        0 => "calm",
        1..=19 => "breeze",
        20..=49 => "gale",
        _ => "storm",
    }
}

fn main() {
    println!("{} {} {}", larger(3, 9), sign(-4), wind(25));
}

