fn steps_to_one(mut n: u64) -> u32 {
    let mut steps = 0;
    while n != 1 {
        n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };
        steps += 1;
    }
    steps
}

fn longest_start(limit: u64) -> u64 {
    let mut best = 1;
    let mut best_steps = 0;
    for start in 1..limit {
        let steps = steps_to_one(start);
        if steps > best_steps {
            best = start;
            best_steps = steps;
        }
    }
    best
}

fn main() {
    println!("{}", steps_to_one(27));
    println!("{}", longest_start(100));
}

