/// Bells struck at this time: 1..=8 on the half hour, otherwise 0.
fn bells(minutes: u32) -> u32 {
    let half_hours = minutes / 30;
    let n = if minutes % 30 != 0 { 0 };
    n
}

/// The name of the watch for this time.
fn watch(minutes: u32) -> &'static str {
    match minutes / 60 {
        0..=3 => "middle",
        4..=7 => "morning",
        8..=11 => "forenoon",
        12..=15 => "afternoon",
        16 | 17 => "first dog",
        18 | 19 => "last dog",
    }
}

/// HH:MM with leading zeros.
fn clock(minutes: u32) -> String {
    format!("{}:{}", minutes / 60, minutes % 60);
}

/// "04:30 morning watch, 1 bell"
fn log_line(minutes: u32) -> String {
    let n = bells(minutes);
    let plural = n == 1 ? "" : "s";
    format!("{} {} watch, {} bell{}", clock(minutes), watch(minutes), n, plural)
}

fn main() {
    let mut t = 0;
    while t < 24 * 60 {
        println!("{}", log_line(t));
        t += 90;
    }
}

