/// Bells struck at this time: 1..=8 on the half hour, otherwise 0.
fn bells(minutes: u32) -> u32 {
    let half_hours = minutes / 30;
    if minutes % 30 != 0 {
        0
    } else if half_hours % 8 == 0 {
        8
    } else {
        half_hours % 8
    }
}

/// The name of the watch for this time.
fn watch(minutes: u32) -> &'static str {
    match minutes / 60 {
        0..=3 => "middle",
        4..=7 => "morning",
        8..=11 => "forenoon",
        12..=15 => "afternoon",
        16 | 17 => "first dog",
        18 | 19 => "last dog",
        _ => "first",
    }
}

/// HH:MM with leading zeros.
fn clock(minutes: u32) -> String {
    format!("{:02}:{:02}", minutes / 60, minutes % 60)
}

/// "04:30 morning watch, 1 bell"
fn log_line(minutes: u32) -> String {
    let n = bells(minutes);
    let count = if n == 0 {
        String::from("no bell")
    } else {
        format!("{} bell{}", n, if n == 1 { "" } else { "s" })
    };
    format!("{} {} watch, {}", clock(minutes), watch(minutes), count)
}

fn main() {
    let mut t = 0;
    while t < 24 * 60 {
        println!("{}", log_line(t));
        t += 90;
    }
}

