        assert_eq!(watch(0), "middle");
        assert_eq!(watch(239), "middle");
        assert_eq!(watch(240), "morning");
        assert_eq!(watch(600), "forenoon");
        assert_eq!(watch(720), "afternoon");
        assert_eq!(watch(960), "first dog");
        assert_eq!(watch(1080), "last dog");
        assert_eq!(watch(1200), "first");
        assert_eq!(watch(1439), "first");
